const items = $input.all();
if (!items.length) throw new Error("Im Ordner 'Aktuell' wurde keine Datei gefunden.");

items.sort((a, b) => {
  const da = new Date(a.json.modifiedTime || 0).getTime();
  const db = new Date(b.json.modifiedTime || 0).getTime();
  return db - da;
});

const latest = items[0];
return [{
  json: {
    ...latest.json,
    trigger_mode: 'manual_demo'
  }
}];

const j = $json || {};
if (!j.id) throw new Error('Keine Trigger-Datei erhalten.');

return [{
  json: {
    id: j.id,
    name: j.name || 'Unbekanntes Dokument',
    mimeType: j.mimeType || '',
    modifiedTime: j.modifiedTime || null,
    webViewLink: j.webViewLink || null,
    trigger_mode: j.trigger_mode || 'google_drive_event'
  }
}];

const extracted = $input.all();
const meta = $('List Current Documents').all();

const docs = extracted.map((item, i) => {
  const m = meta[i]?.json || {};
  const text = String(item.json.text ?? item.json.data ?? '').trim();
  return {
    id: m.id || '',
    name: m.name || `Datei ${i + 1}`,
    modifiedTime: m.modifiedTime || null,
    webViewLink: m.webViewLink || null,
    text: text.slice(0, 16000)
  };
}).filter(d => d.text);

return [{ json: { current_documents: docs } }];

const extracted = $input.all();
const meta = $('List Archive Documents').all();

const docs = extracted.map((item, i) => {
  const m = meta[i]?.json || {};
  const text = String(item.json.text ?? item.json.data ?? '').trim();
  return {
    id: m.id || '',
    name: m.name || `Datei ${i + 1}`,
    modifiedTime: m.modifiedTime || null,
    webViewLink: m.webViewLink || null,
    text: text.slice(0, 16000)
  };
}).filter(d => d.text);

return [{ json: { archive_documents: docs } }];

const extracted = $input.all();
const meta = $('List Review Targets').all();

const docs = extracted.map((item, i) => {
  const m = meta[i]?.json || {};
  const text = String(item.json.text ?? item.json.data ?? '').trim();
  return {
    id: m.id || '',
    name: m.name || `Datei ${i + 1}`,
    modifiedTime: m.modifiedTime || null,
    webViewLink: m.webViewLink || null,
    text: text.slice(0, 16000)
  };
}).filter(d => d.text);

return [{ json: { review_targets: docs } }];

const cfg = $('Workflow Configuration').first().json;
const current = $('Aggregate Current Corpus').first().json.current_documents || [];
const archive = $('Aggregate Archive Corpus').first().json.archive_documents || [];
const targets = $('Aggregate Review Targets').first().json.review_targets || [];

function corpus(title, docs) {
  if (!docs.length) return `=== ${title} ===\n[keine Dokumente vorhanden]`;
  return `=== ${title} ===\n` + docs.map((d, i) =>
    `--- Datei ${i + 1}: ${d.name} | ID: ${d.id} ---\n${d.text}`
  ).join('\n\n');
}

const prompt = `
AUFGABE
Ein Google-Drive-Dokument im Ordner "Aktuell" wurde neu angelegt oder geändert.
Führe einen Content-Review durch und erstelle ausschließlich Hinweise für eine menschliche Prüfung.

AUSLÖSENDES DOKUMENT
Dateiname: ${cfg.triggerFileName}
Drive-ID: ${cfg.triggerFileId}
Änderungszeitpunkt: ${cfg.triggerModifiedTime || 'unbekannt'}

PRÜFLOGIK
1. Identifiziere das auslösende Dokument im aktuellen Dokumentbestand.
2. Nutze den Archivbestand als historischen Kontext. Es muss KEIN 1:1-Vorgängerdokument existieren.
3. Erkenne relevante Abweichungen zwischen aktuellem Dokument und historischen, thematisch passenden Dokumenten, soweit dies aus den bereitgestellten Texten hervorgeht.
4. Prüfe den GESAMTEN aktuellen Governance-Bestand auf mögliche Widersprüche, Überschneidungen, Unklarheiten oder neue Anforderungen, die durch das auslösende Dokument relevant werden.
5. Prüfe ALLE bereitgestellten Review-Ziele auf möglichen Anpassungsbedarf.
6. Nenne konkrete Content-/Question-IDs nur, wenn sie im bereitgestellten Material tatsächlich vorkommen.
7. Formuliere konkrete Anpassungsvorschläge, ändere aber NICHTS automatisch.

WICHTIGE GRENZEN
- Arbeite ausschließlich mit den bereitgestellten Dokumenten.
- Nutze kein externes Wissen.
- Triff keine juristische oder fachliche Letztentscheidung.
- Ein ungewöhnlicher oder offensichtlich absurder Inhalt darf als besonders prüfbedürftig markiert werden, wenn er mit bereitgestellten aktuellen/historischen Inhalten oder Schulungsinhalten kollidiert.
- Das Archiv ist historischer Kontext und nicht automatisch aktuell gültig.
- Wenn es keinen belastbaren Alt-Neu-Vergleich gibt, sage das.
- Sobald ein relevanter Prüfpunkt existiert, muss overall_status = "review_required" sein.
- Die Ausgabe muss exakt dem Structured Output Parser entsprechen.

${corpus('AKTUELLER GOVERNANCE-BESTAND', current)}

${corpus('ARCHIV / HISTORISCHER KONTEXT', archive)}

${corpus('AKTUELLE LERN- UND PRÜFUNGSINHALTE / REVIEW-ZIELE', targets)}
`.trim();

return [{
  json: {
    reviewPrompt: prompt,
    recipientEmail: cfg.recipientEmail,
    triggerFileName: cfg.triggerFileName,
    triggerFileId: cfg.triggerFileId,
    triggerMode: cfg.triggerMode
  }
}];

let review = $json.output ?? $json;

if (typeof review === 'string') {
  const cleaned = review
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  review = JSON.parse(cleaned);
}

const cfg = $('Workflow Configuration').first().json;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const meta = {
  high:   { label: 'HOCH', bg: '#FDECEC', fg: '#9F1D1D' },
  medium: { label: 'MITTEL', bg: '#FFF4D8', fg: '#8A5A00' },
  low:    { label: 'NIEDRIG', bg: '#EAF3FF', fg: '#1557A0' }
};

function badge(level) {
  const m = meta[level] || meta.low;
  return `<span style="display:inline-block;padding:4px 8px;border-radius:999px;background:${m.bg};color:${m.fg};font-size:11px;font-weight:700">${m.label}</span>`;
}

function empty(text) {
  return `<div style="padding:14px 16px;background:#F7F9FC;border:1px solid #E5EAF1;border-radius:10px;color:#596579">${esc(text)}</div>`;
}

const historical = Array.isArray(review.historical_comparison) && review.historical_comparison.length
  ? review.historical_comparison.map(x => `
    <div style="padding:16px;border:1px solid #E5EAF1;border-radius:12px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;gap:12px">
        <strong style="color:#102A56">${esc(x.topic)}</strong>${badge(x.severity)}
      </div>
      <div style="margin-top:6px;font-size:12px;color:#667085">${esc(x.historical_document)} · ${esc(x.classification)}</div>
      <div style="margin-top:10px;font-size:13px"><strong>Historisch:</strong> ${esc(x.historical_statement)}</div>
      <div style="margin-top:6px;font-size:13px"><strong>Aktuell:</strong> ${esc(x.current_statement)}</div>
      <div style="margin-top:8px;font-size:13px;line-height:1.5"><strong>Relevanz:</strong> ${esc(x.why_relevant)}</div>
    </div>`).join('')
  : empty('Kein belastbarer historischer Vergleich erforderlich oder möglich.');

const conflicts = Array.isArray(review.current_document_conflicts) && review.current_document_conflicts.length
  ? review.current_document_conflicts.map(x => `
    <div style="padding:16px;border-left:4px solid #D14343;background:#FFF7F7;border-radius:10px;margin-bottom:12px">
      <div>${badge(x.severity)} <strong style="margin-left:8px;color:#102A56">${esc((x.documents || []).join(' ↔ '))}</strong></div>
      <div style="margin-top:9px;font-size:13px;line-height:1.55"><strong>Befund:</strong> ${esc(x.finding)}</div>
      <div style="margin-top:6px;font-size:13px;line-height:1.55"><strong>Vorschlag:</strong> ${esc(x.recommendation)}</div>
    </div>`).join('')
  : empty('Keine konkreten Widersprüche im aktuellen Bestand erkannt.');

const training = Array.isArray(review.training_findings) && review.training_findings.length
  ? review.training_findings.map(x => `
    <div style="padding:16px;border:1px solid #E5EAF1;border-radius:12px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;gap:12px">
        <div><strong style="color:#102A56">${esc(x.content_id)}</strong>
        <span style="font-size:12px;color:#667085"> · ${esc(x.content_type)}</span></div>
        ${badge(x.severity)}
      </div>
      ${x.current_content ? `<div style="margin-top:10px;padding:10px 12px;background:#F7F9FC;border-radius:8px;font-size:13px"><strong>Aktueller Inhalt:</strong> ${esc(x.current_content)}</div>` : ''}
      <div style="margin-top:10px;font-size:13px;line-height:1.55"><strong>Prüfgrund:</strong> ${esc(x.reason)}</div>
      <div style="margin-top:6px;font-size:13px;line-height:1.55"><strong>Anpassungsvorschlag:</strong> ${esc(x.recommendation)}</div>
    </div>`).join('')
  : empty('Keine konkreten Lern- oder Prüfungsstellen zur Anpassungsprüfung erkannt.');

const questions = Array.isArray(review.human_review_questions) && review.human_review_questions.length
  ? `<ul style="margin:8px 0 0 20px;padding:0">${review.human_review_questions.map(q => `<li style="margin:7px 0">${esc(q)}</li>`).join('')}</ul>`
  : '<p style="margin:8px 0 0">Keine zusätzlichen Review-Fragen.</p>';

const needsReview = review.overall_status === 'review_required';
const statusLabel = needsReview ? 'MENSCHLICHE PRÜFUNG ERFORDERLICH' : 'KEIN RELEVANTER ANPASSUNGSBEDARF';
const statusBg = needsReview ? '#FFF0F0' : '#ECF8F1';
const statusFg = needsReview ? '#9F1D1D' : '#146B3A';

const html = `
<!doctype html>
<html>
<body style="margin:0;padding:0;background:#F4F7FA;font-family:Arial,Helvetica,sans-serif;color:#182230">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#F4F7FA;padding:24px 10px">
<tr><td align="center">
<table role="presentation" width="720" cellspacing="0" cellpadding="0" style="width:100%;max-width:720px;background:#FFFFFF;border-radius:14px;overflow:hidden;border:1px solid #E5EAF1">
<tr><td style="background:#006BB6;padding:24px 28px;color:#FFFFFF">
<div style="font-size:12px;letter-spacing:.08em;font-weight:700;opacity:.9">ZUKUNFTSFIRMA · AI ONBOARDING</div>
<h1 style="font-size:24px;line-height:1.25;margin:8px 0 0">Automatischer Content-Review</h1>
</td></tr>
<tr><td style="padding:26px 28px">
<div style="display:inline-block;padding:7px 10px;border-radius:999px;background:${statusBg};color:${statusFg};font-size:11px;font-weight:700">${statusLabel}</div>
<h2 style="font-size:19px;color:#102A56;margin:18px 0 8px">${esc(review.trigger_document || cfg.triggerFileName)}</h2>
<p style="font-size:14px;line-height:1.6;color:#4A5568;margin:0">${esc(review.executive_summary)}</p>

<h3 style="font-size:16px;color:#006BB6;margin:30px 0 12px">1. Historischer Vergleich</h3>
${historical}

<h3 style="font-size:16px;color:#006BB6;margin:30px 0 12px">2. Mögliche Widersprüche im aktuellen Bestand</h3>
${conflicts}

<h3 style="font-size:16px;color:#006BB6;margin:30px 0 12px">3. Zu prüfende Lern- und Prüfungsinhalte</h3>
${training}

<h3 style="font-size:16px;color:#006BB6;margin:30px 0 12px">4. Fragen für die menschliche Prüfung</h3>
<div style="padding:15px 18px;background:#F2F7FD;border-radius:10px;font-size:13px;line-height:1.55">${questions}</div>

<div style="margin-top:30px;padding:16px 18px;background:#F7F9FC;border-radius:10px;color:#667085;font-size:12px;line-height:1.55">
<strong>Hinweis:</strong> ${esc(review.disclaimer || 'Automatisierter Review-Hinweis. Es wurden keine Inhalte automatisch verändert. Die finale Entscheidung liegt bei einem Menschen.')}
</div>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

return [{
  json: {
    recipientEmail: cfg.recipientEmail,
    subject: `[AI-Onboarding] Review – ${review.trigger_document || cfg.triggerFileName}`,
    html,
    review
  }
}];
